            { text: 'He said me to give him my password, but I didn\'t.', why: '"Say" can\'t have a person after it. Use "He told me to…".' },
            { text: 'He told me give him my password, but I didn\'t.', why: 'After "told me", use "to" + verb: "told me to give".' }
